<header class="admin-page-head"><div><p class="admin-eyebrow">تیم / دسترسی‌ها</p><h1>نقش‌ها و دسترسی‌ها</h1><p class="admin-lede">تعریف سطح دسترسی برای بخش‌های مختلف کنسول مدیریتی رسپینا.</p></div><a class="admin-primary-button" href="<?= e(admin_url('/roles/new')) ?>">ایجاد نقش جدید <span aria-hidden="true">→</span></a></header>
<?php if (!empty($admin_error)): ?><div class="admin-alert error" role="alert"><?= e($admin_error) ?></div><?php endif; ?><section class="admin-panel admin-table-panel"><div class="table-toolbar"><div><p class="admin-eyebrow">نقشه دسترسی‌ها</p><h2>نقش‌ها و اختیارات</h2></div><span class="toolbar-meta"><?= count((array) $roles) ?> نقش تعریف شده</span></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>عنوان نقش و توضیحات</th><th>نوع نقش</th><th>تعداد کاربران</th><th>تعداد اختیارات</th><th><span class="sr-only">عملیات</span></th></tr></thead><tbody><?php foreach ((array) $roles as $role): ?><tr><td class="table-primary" data-label="Role"><a href="<?= e(admin_url('/roles/edit/' . (int) $role['id'])) ?>"><?= e($role['title']) ?></a><small><?= e($role['description']) ?></small></td><td data-label="Kind"><?= !empty($role['is_system']) ? 'سیستمی (محفوظ)' : 'سفارشی' ?></td><td data-label="Users"><span class="count-badge"><?= (int) $role['user_count'] ?> نفر</span></td><td data-label="Permissions"><?= (int) $role['permission_count'] ?> مورد مجاز</td><td data-label="Actions"><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/roles/edit/' . (int) $role['id'])) ?>">ویرایش</a><?php if (empty($role['is_system'])): ?><form method="post" action="<?= e(admin_url('/roles')) ?>" data-confirm="آیا می‌خواهید این نقش سفارشی را حذف کنید؟"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_role"><input type="hidden" name="id" value="<?= (int) $role['id'] ?>"><button class="icon-action danger" type="submit">حذف</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$roles): ?><div class="empty-state"><div><strong>هیچ نقشی پیدا نشد</strong><p>مهاجرت مربوط به جدول دسترسی تیم را ایمپورت کنید و این صفحه را مجدداً لود کنید.</p></div></div><?php endif; ?></section>
